$ErrorActionPreference='Stop';$meta=Get-Content -Raw -LiteralPath (Join-Path $PSScriptRoot 'developer.json')|ConvertFrom-Json;if($meta.Login-notmatch'^g5_[a-z0-9][a-z0-9_-]{1,30}$'-or$meta.Port-ne 5673){throw 'Invalid G5 developer package metadata.'}
& (Join-Path $PSScriptRoot 'scripts\Test-G5RabbitMqTunnel.ps1');$credential=Import-Clixml (Join-Path $PSScriptRoot 'secrets\g5_ventas.clixml');$secret=[Net.NetworkCredential]::new('', $credential).Password;$escaped=[uri]::EscapeDataString($secret);$env:RABBITMQ_URL="amqp://g5_ventas:$escaped@127.0.0.1:5673/g6-productos-ofertas"
$temp=Join-Path $env:TEMP ('g5-amqp-smoke-'+[Guid]::NewGuid().ToString('N'));$null=New-Item -ItemType Directory -Path $temp
try{'{"private":true,"type":"module"}'|Set-Content -LiteralPath (Join-Path $temp 'package.json') -Encoding ascii;& npm.cmd install --prefix $temp --no-audit --no-fund amqplib@2.2.0;if($LASTEXITCODE-ne 0){throw 'Could not prepare temporary AMQP dependency.'};Copy-Item (Join-Path $PSScriptRoot 'scripts\verify-g5-ventas-amqp.mjs') (Join-Path $temp 'verify.mjs');& node (Join-Path $temp 'verify.mjs');if($LASTEXITCODE-ne 0){throw 'G5 AMQP smoke failed; secrets were not printed.'}}finally{$env:RABBITMQ_URL=$null;$secret=$null;$credential.Dispose();$base=[IO.Path]::GetFullPath($env:TEMP).TrimEnd([IO.Path]::DirectorySeparatorChar)+[IO.Path]::DirectorySeparatorChar;$resolved=[IO.Path]::GetFullPath($temp);if(-not$resolved.StartsWith($base,[StringComparison]::OrdinalIgnoreCase)){throw 'Refusing to remove a temp folder outside Windows TEMP.'};Remove-Item -LiteralPath $resolved -Recurse -Force}
